import React from 'react';
import { Guest } from './index';

const previews = {
  componentName: 'Guest',
  importPath: 'components/Guest',
  previews: [
    { name: '3D rig', description: "A park guest with an animated walk cycle, modelled from the RCT2 peep sprite. Drag to orbit.", render: () => <Guest /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box, ball } from '../Stage';

// Shared peep builder — used by the Guest crowd and seated in rides. Supports
// varied skin tones, hair, shirt/trousers colours and facial EXPRESSIONS
// (happy / neutral / sad / surprised). Limbs pivot for a walk cycle or sit.
export type Expression = 'happy' | 'neutral' | 'sad' | 'surprised';
export interface PeepOpts {
  shirt?: number;
  trousers?: number;
  skin?: number;
  hair?: number;
  expression?: Expression;
  seated?: boolean;
}
export const SKIN_TONES = [0xf1c9a5, 0xe0a878, 0xc68642, 0x8d5524, 0x5c3a21];
export const SHIRTS = [0xc21a1a, 0x2f6fd0, 0x2e9e54, 0xe0a020, 0x8e44ad, 0xe06010, 0x18a0a0, 0xe060a0];
export const TROUSERS = [0x26305e, 0x3a2a1a, 0x333940, 0x5a3d22, 0x6a1030];
export const HAIRS = [0x4a3018, 0x1c1c1c, 0x7a5230, 0xb08040, 0x9a9a9a];

export function buildPeep(t: typeof THREE, o: PeepOpts = {}) {
  const SKIN = o.skin ?? 0xe0a878;
  const HAIR = o.hair ?? 0x4a3018;
  const SHIRT = o.shirt ?? 0xc21a1a;
  const TROU = o.trousers ?? 0x26305e;
  const SHOE = 0x2a1c10;
  const DARK = 0x1a1207;
  const expr = o.expression ?? 'happy';

  const grp = new t.Group();
  grp.add(box(t, [0.26, 0.14, 0.18], TROU, [0, 0.52, 0], { tex: 'fabric', repeat: [2, 1], rough: 0.9 }));
  grp.add(box(t, [0.3, 0.32, 0.2], SHIRT, [0, 0.74, 0], { tex: 'fabric', repeat: [2, 2], rough: 0.85 }));

  const head = new t.Group();
  head.position.set(0, 0.99, 0);
  head.add(ball(t, 0.12, SKIN, [0, 0, 0], { rough: 0.7 }));
  const hair = ball(t, 0.128, HAIR, [0, 0.04, -0.012], { rough: 0.9 });
  hair.scale.set(1.02, 0.72, 1.02);
  head.add(hair);

  const eyeR = expr === 'surprised' ? 0.032 : 0.026;
  [-0.045, 0.045].forEach((ex) => {
    head.add(ball(t, eyeR, 0xffffff, [ex, 0.02, 0.104], { rough: 0.4 }));
    head.add(ball(t, 0.013, 0x1b1b22, [ex, 0.02, 0.121], { rough: 0.3 }));
    const browTilt = expr === 'sad' ? (ex > 0 ? 0.35 : -0.35) : ex > 0 ? -0.15 : 0.15;
    head.add(box(t, [0.05, 0.012, 0.01], HAIR, [ex, expr === 'sad' ? 0.05 : 0.062, 0.108], { rotZ: browTilt }));
  });

  // mouth by expression
  if (expr === 'surprised') {
    head.add(ball(t, 0.028, DARK, [0, -0.04, 0.108], { rough: 0.5 }));
  } else if (expr === 'neutral') {
    head.add(box(t, [0.06, 0.012, 0.012], DARK, [0, -0.045, 0.11]));
  } else {
    const m = new t.Mesh(new t.TorusGeometry(0.035, 0.008, 8, 12, Math.PI), new t.MeshStandardMaterial({ color: DARK, roughness: 0.5 }));
    m.rotation.set(expr === 'sad' ? 0 : Math.PI, 0, 0);
    m.position.set(0, expr === 'sad' ? -0.06 : -0.035, 0.108);
    head.add(m);
  }
  head.add(ball(t, 0.018, SKIN, [0, -0.005, 0.12], { rough: 0.6 })); // nose
  grp.add(head);

  const limb = (px: number, py: number, col: number, len: number, hand?: number, texd?: boolean) => {
    const pivot = new t.Group();
    pivot.position.set(px, py, 0);
    pivot.add(box(t, [0.09, len, 0.11], col, [0, -len / 2, 0], texd ? { tex: 'fabric', repeat: [1, 2], rough: 0.85 } : { rough: 0.7 }));
    if (hand != null) pivot.add(ball(t, 0.05, hand, [0, -len, 0], { rough: 0.7 }));
    grp.add(pivot);
    return pivot;
  };
  const armL = limb(-0.19, 0.88, SHIRT, 0.32, SKIN, true);
  const armR = limb(0.19, 0.88, SHIRT, 0.32, SKIN, true);
  const legL = limb(-0.08, 0.46, TROU, 0.4, undefined, true);
  const legR = limb(0.08, 0.46, TROU, 0.4, undefined, true);
  legL.add(box(t, [0.12, 0.07, 0.2], SHOE, [0, -0.4, 0.03], { rough: 0.6 }));
  legR.add(box(t, [0.12, 0.07, 0.2], SHOE, [0, -0.4, 0.03], { rough: 0.6 }));

  if (o.seated) {
    legL.rotation.x = -1.5;
    legR.rotation.x = -1.5;
    armL.rotation.x = -1.1;
    armR.rotation.x = -1.1;
    if (expr === 'surprised') {
      armL.rotation.x = -2.6; // arms up!
      armR.rotation.x = -2.6;
    }
  }

  const walk = (time: number, phase = 0) => {
    const s = Math.sin(time * 5 + phase);
    legL.rotation.x = s * 0.5;
    legR.rotation.x = -s * 0.5;
    armL.rotation.x = -s * 0.45;
    armR.rotation.x = s * 0.45;
    grp.position.y = Math.abs(Math.cos(time * 5 + phase)) * 0.03;
  };
  return { group: grp, walk, head };
}

// A diverse crowd of walking guests — varied skin tones, outfits and moods.
export function Guest() {
  return (
    <Stage
      distance={5.2}
      targetY={0.6}
      autoRotate
      build={(t, g) => {
        const exprs: Expression[] = ['happy', 'neutral', 'surprised', 'happy', 'sad'];
        const peeps = exprs.map((expression, i) => {
          const p = buildPeep(t, {
            skin: SKIN_TONES[i % SKIN_TONES.length],
            hair: HAIRS[i % HAIRS.length],
            shirt: SHIRTS[i % SHIRTS.length],
            trousers: TROUSERS[i % TROUSERS.length],
            expression,
          });
          p.group.position.set((i - 2) * 0.85, 0, (i % 2) * 0.4 - 0.2);
          p.group.rotation.y = 0.3;
          g.add(p.group);
          return p;
        });
        return (time) => peeps.forEach((p, i) => p.walk(time, i * 1.3));
      }}
    />
  );
}

import React from 'react';
import { CoasterCar } from './index';

const previews = {
  componentName: 'CoasterCar',
  importPath: 'components/CoasterCar',
  previews: [
    { name: '3D rig', description: "A single wooden-coaster car with seated riders, modelled from the RCT2 vehicle sprite. Drag to orbit.", render: () => <CoasterCar /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// A wooden-coaster car, detailed from the RCT2 vehicle sprite: a rounded orange
// tub with a swept nose + tail coupler, chrome side trim, a headlight, two
// bogies of wheels, over-shoulder restraints, and two seated peeps (diverse
// skin + shirts, each with a face). Exported so WoodenCoaster builds a train.
export function buildCoasterCar(t: typeof THREE): THREE.Group {
  const g = new t.Group();
  const ORANGE = 0xe0601a;
  const ORANGE_D = 0xb5480f;
  const CHROME = 0xcfd4da;
  const DARK = 0x232327;
  const SEAT = 0x191a1e;

  // chassis + bogies
  g.add(box(t, [0.5, 0.1, 1.0], DARK, [0, 0.02, 0], { tex: 'metal', repeat: [3, 5], metal: 0.7, rough: 0.5 }));
  [-0.34, 0.34].forEach((z) => g.add(box(t, [0.56, 0.08, 0.24], DARK, [0, -0.04, z], { tex: 'metal', metal: 0.6, rough: 0.5 })));

  // tub: layered boxes for a rounded hull
  g.add(box(t, [0.58, 0.3, 1.0], ORANGE, [0, 0.24, 0], { tex: 'plastic', repeat: [2, 1], rough: 0.38 }));
  g.add(box(t, [0.64, 0.16, 0.94], ORANGE, [0, 0.2, 0], { tex: 'plastic', repeat: [2, 1], rough: 0.38 }));
  g.add(box(t, [0.5, 0.28, 0.86], SEAT, [0, 0.34, 0], { rough: 0.85 })); // interior well
  // chrome waist trim + number panel
  g.add(box(t, [0.66, 0.04, 0.96], CHROME, [0, 0.33, 0], { tex: 'metal', metal: 0.9, rough: 0.2 }));
  g.add(box(t, [0.52, 0.14, 0.02], 0xf5e6c8, [0, 0.24, 0.505], { rough: 0.5 })); // front panel
  // swept nose (front +z) + headlight
  g.add(box(t, [0.5, 0.26, 0.3], ORANGE_D, [0, 0.2, 0.56], { rotX: -0.7, tex: 'plastic', repeat: [1, 1], rough: 0.38 }));
  g.add(ball(t, 0.05, 0xfff3c0, [0, 0.24, 0.66], { emissive: 0xffcc55, rough: 0.3 }));
  // tail coupler
  g.add(cyl(t, 0.04, 0.04, 0.16, CHROME, [0, 0.18, -0.58], { rotX: Math.PI / 2, metal: 0.9, rough: 0.2, seg: 10 }));

  // two seated peeps front/back with restraints
  [0.2, -0.16].forEach((z, i) => {
    g.add(box(t, [0.46, 0.24, 0.05], SEAT, [0, 0.4, z - 0.2], { rough: 0.85 })); // seat back
    const p = buildPeep(t, { skin: SKIN_TONES[i], shirt: SHIRTS[(i * 3 + 2) % SHIRTS.length], seated: true, expression: i === 0 ? 'surprised' : 'happy' });
    p.group.scale.setScalar(0.52);
    p.group.position.set(0, 0.12, z);
    g.add(p.group);
    // over-shoulder restraint
    g.add(cyl(t, 0.02, 0.02, 0.34, DARK, [0, 0.62, z + 0.02], { rotZ: Math.PI / 2, metal: 0.5, rough: 0.4, seg: 8 }));
    [-0.12, 0.12].forEach((x) => g.add(cyl(t, 0.018, 0.018, 0.24, DARK, [x, 0.52, z + 0.06], { rotX: 0.5, metal: 0.5, rough: 0.4, seg: 8 })));
  });

  const wheel = (x: number, z: number) =>
    cyl(t, 0.1, 0.1, 0.07, 0x141417, [x, -0.05, z], { rotZ: Math.PI / 2, tex: 'metal', repeat: [4, 1], metal: 0.6, rough: 0.4, seg: 20 });
  [
    [-0.3, 0.34],
    [0.3, 0.34],
    [-0.3, -0.34],
    [0.3, -0.34],
  ].forEach(([x, z]) => g.add(wheel(x, z)));

  return g;
}

export function CoasterCar() {
  return (
    <Stage
      distance={4.2}
      targetY={0.45}
      build={(t, g) => {
        const TIE = 0x6b4626;
        for (let z = -1.4; z <= 1.4; z += 0.4) g.add(box(t, [0.98, 0.06, 0.12], TIE, [0, 0.02, z], { tex: 'wood', repeat: [3, 1], rough: 0.9 }));
        g.add(box(t, [0.07, 0.08, 3.0], 0x8b8f96, [-0.32, 0.09, 0], { tex: 'metal', repeat: [1, 20], metal: 0.85, rough: 0.3 }));
        g.add(box(t, [0.07, 0.08, 3.0], 0x8b8f96, [0.32, 0.09, 0], { tex: 'metal', repeat: [1, 20], metal: 0.85, rough: 0.3 }));
        const car = buildCoasterCar(t);
        car.position.y = 0.25;
        g.add(car);
        return (time) => {
          car.position.y = 0.25 + Math.sin(time * 2) * 0.015;
          car.rotation.z = Math.sin(time * 1.3) * 0.015;
        };
      }}
    />
  );
}
